import serial

def crc16(data):
    crc = 0xFFFF
    for pos in data:
        crc ^= pos
        for i in range(8):
            if (crc & 0x0001):
                crc >>= 1
                crc ^= 0xA001
            else:
                crc >>= 1
    return crc.to_bytes(2, 'little')

ser = serial.Serial('/dev/ttyUSB0', baudrate=9600, bytesize=8, parity='N', stopbits=1, timeout=1)
slave_id = 3
function = 0x03          # Read Holding Registers
start_addr = 0x0010
qty = 2
request = bytearray([slave_id, function]) + start_addr.to_bytes(2, 'big') + qty.to_bytes(2, 'big')
request += crc16(request)
ser.write(request)
response = ser.read(5 + qty*2)   # address+func+bytecnt+data+crc
if len(response) == 5 + qty*2:
    data = response[3:-2]
    print('Registers:', [int.from_bytes(data[i:i+2], 'big') for i in range(0, len(data), 2)])
else:
    print('No valid response – check wiring, address, or baud rate')

